def transform(payloads, contract):
    """Transform builds evidence payloads into ranked evidence records."""
    name = contract["name"]
    offset = contract.get("offset", 0)

    raw_records = _unwrap_payload(payloads[0])
    if not isinstance(raw_records, list):
        raise TransformError("builds input must be an array of records")

    normalized_records = [_parse_record(r) for r in raw_records]

    # Keep only the highest revision for each id. Duplicate identical records
    # for the same id/revision are collapsed; conflicting duplicates error.
    by_id = {}
    for record in normalized_records:
        by_id.setdefault(record["id"], []).append(record)

    selected = []
    for record_id, records in by_id.items():
        max_revision = max(r["revision"] for r in records)
        latest = [r for r in records if r["revision"] == max_revision]

        seen = {}
        for record in latest:
            key = _record_key(record)
            if key in seen:
                continue
            seen[key] = record

        if len(seen) > 1:
            raise TransformError(
                f"conflicting duplicate records for id {record_id!r} revision {max_revision}"
            )
        selected.append(next(iter(seen.values())))

    records = []
    score_total = 0
    for record in selected:
        base = math.ceil(20 * record["failures"] / record["total"])
        score = max(0, min(20, base + offset))
        output_record = {
            "id": record["id"],
            "source": name,
            "owner": record["owner"],
            "category": record["category"],
            "tags": record["tags"],
            "score": score,
        }
        records.append(output_record)
        score_total += score

    records.sort(key=lambda r: (r["source"], r["id"]))

    return {
        "name": name,
        "result": {
            "records": records,
            "count": len(records),
            "score_total": score_total,
        },
    }
